using sv_2c83f06ae1724d9a866f0d5e3becb249.Services;

namespace sv_2c83f06ae1724d9a866f0d5e3becb249.Components.Pages;

public partial class Settings
{
    private string activeSection = "Profile";
    private bool loading = true;
    private string? toastMessage;
    private CancellationTokenSource? toastCts;

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileBio = "";
    private string profileAvatarUrl = "";
    private UserProfile? savedProfile;

    // Notifications state
    private bool notifEmail;
    private bool notifPush;
    private bool notifWeeklyDigest;
    private List<string> mutedChannels = new();
    private List<string>? channels;

    // Security state
    private SecuritySettings? securitySettings;
    private List<ActiveSession>? sessions;
    private bool twoFactorEnabled;
    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private ActiveSession? sessionToRevoke;

    // Appearance state
    private string appearanceTheme = "System";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "en";
    private bool appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
        loading = false;
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        loading = true;
        await LoadSectionData();
        loading = false;
    }

    private async Task LoadSectionData()
    {
        switch (activeSection)
        {
            case "Profile":
                var profile = await SettingsService.GetProfileAsync();
                savedProfile = profile;
                profileDisplayName = profile.DisplayName;
                profileEmail = profile.Email;
                profileBio = profile.Bio;
                profileAvatarUrl = profile.AvatarUrl;
                break;

            case "Notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                notifEmail = prefs.EmailNotifications;
                notifPush = prefs.PushNotifications;
                notifWeeklyDigest = prefs.WeeklyDigest;
                mutedChannels = new List<string>(prefs.MutedChannels);
                // Provide a default channel list (in a real app this would come from a service)
                channels ??= new List<string> { "general", "announcements", "random", "support", "engineering" };
                break;

            case "Security":
                securitySettings = await SettingsService.GetSecuritySettingsAsync();
                twoFactorEnabled = securitySettings.TwoFactorEnabled;
                sessions = securitySettings.Sessions.ToList();
                break;

            case "Appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                appearanceTheme = appearance.Theme;
                appearanceFontSize = appearance.FontSize;
                appearanceLanguage = appearance.Language;
                appearanceCompactMode = appearance.CompactMode;
                break;
        }
    }

    // ─── Profile actions ───

    private async Task SaveProfile()
    {
        var updated = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile is not null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileBio = savedProfile.Bio;
            profileAvatarUrl = savedProfile.AvatarUrl;
        }
    }

    // ─── Notifications actions ───

    private bool IsChannelMuted(string channel) => mutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!muted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(notifEmail, notifPush, notifWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // ─── Security actions ───

    private async Task UpdatePassword()
    {
        passwordError = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            passwordPanelOpen = false;
            await ShowToast("Password updated successfully!");
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            sessions?.Remove(sessionToRevoke);
            sessionToRevoke = null;
            await ShowToast("Session revoked.");
        }
    }

    // ─── Appearance actions ───

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{appearanceTheme.ToLowerInvariant()} preview-font-{appearanceFontSize.ToLowerInvariant()}";
        if (appearanceCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    // ─── Toast helper ───

    private async Task ShowToast(string message)
    {
        toastCts?.Cancel();
        toastCts = new CancellationTokenSource();
        var token = toastCts.Token;

        toastMessage = message;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }
}

